#!/usr/bin/env python3
"""Convert 'VALUE UNIT' lines read from stdin."""
import sys


def convert(line):
    value_text, unit = line.split()
    value = float(value_text)
    unit = unit.lower()
    if unit == "c":
        return f"{value * 9 / 5 + 32:.1f} F"
    if unit == "f":
        return f"{(value - 32) * 5 / 9:.1f} C"
    if unit == "km":
        return f"{value / 1.609344:.2f} mi"
    if unit == "mi":
        return f"{value * 1.609344:.2f} km"
    return "unknown unit " + unit


for line in sys.stdin:
    line = line.strip()
    if line:
        print(line, "->", convert(line))
